const product = $input.item.json;
const mpEmoji = product.marketplace.toLowerCase() === 'wildberries' || product.marketplace.toLowerCase() === 'wb' ? '🟣' : '🔵';

let message = `🚨 *КРИТИЧЕСКАЯ УГРОЗА МАРЖИ!*\n\n`;
message += `${mpEmoji} *${product.product_title}*\n`;
message += `${product.marketplace}\n\n`;

message += `📊 *UNIT ECONOMICS:*\n`;
const econ = product.economics;
message += `├─ Цена: ${econ.revenue}₽\n`;
message += `├─ Себестоимость: ${econ.costPrice}₽\n`;
message += `├─ Комиссия: ${econ.commission}₽ (${(econ.commissionRate * 100).toFixed(1)}%)\n`;
message += `├─ Логистика: ${econ.logistics}₽\n`;
if (econ.ozonCardCosts > 0) {
  message += `├─ Ozon Card: ${econ.ozonCardCosts}₽\n`;
}
message += `└─ ПРИБЫЛЬ: ${econ.profit}₽ (${econ.margin}%)\n\n`;

message += `⚠️ *РИСКИ:*\n`;
product.warnings.forEach(w => {
  if (w.type === 'critical') {
    message += `🚨 ${w.message}\n`;
  }
});

message += `\n💡 *Viktor Margin*\n`;
message += `_Срочно требуется действие!_`;

return [{ json: {
    message: message,
    chat_id: $('Configuration').first().json.adminChatId
  }}];

const items = $input.all();

let message = `📊 *VIKTOR MARGIN: Hourly Report*

`;
message += `⚠️ Обнаружено ${items.length} товаров с предупреждениями

`;

const warningTypes = {};
items.forEach(item => {
  item.json.warnings.forEach(w => {
    if (w.type === 'warning') {
      warningTypes[w.code] = (warningTypes[w.code] || 0) + 1;
    }
  });
});

message += `*Типы предупреждений:*
`;
Object.entries(warningTypes).forEach(([code, count]) => {
  const label = code === 'OZON_CARD_IMPACT' ? 'Ozon Card' :
                code === 'HIGH_STORAGE_DAYS' ? 'Долгое хранение' :
                code === 'HIGH_RETURN_RATE' ? 'Высокий возврат' : code;
  message += `  • ${label}: ${count}
`;
});

message += `
💡 *Viktor Margin*
`;
message += `_Проверьте детали в dashboard_`;

return {
  json: {
    message: message
  }
};

