const items = $input.all();

let successCount = 0;
let errorCount = 0;
let validationFailedCount = 0;
const successProducts = [];
const errorProducts = [];

for (const item of items) {
  const status = item.json.execution_status;
  const marketplace = item.json.marketplace || 'unknown';
  const productId = item.json.product_id || item.json.offer_id || 'unknown';
  const action = item.json.defense_action || 'unknown';

  if (status === 'success') {
    successCount++;
    successProducts.push(`${marketplace.toUpperCase()}: ${productId} (${action})`);
  } else if (status === 'validation_failed') {
    validationFailedCount++;
    errorProducts.push(`${marketplace.toUpperCase()}: ${productId} - Validation Failed`);
  } else {
    errorCount++;
    const errorReason = item.json.error_reason || 'Unknown error';
    errorProducts.push(`${marketplace.toUpperCase()}: ${productId} - ${errorReason}`);
  }
}

let message = `🛡️ *Defense System Report*\n\n`;
message += `✅ Successful: ${successCount}\n`;
message += `❌ Failed: ${errorCount}\n`;
message += `⚠️ Validation Failed: ${validationFailedCount}\n`;
message += `📊 Total Processed: ${items.length}\n\n`;

if (successProducts.length > 0) {
  message += `*Successful Actions:*\n`;
  successProducts.forEach(p => message += `  • ${p}\n`);
  message += `\n`;
}

if (errorProducts.length > 0) {
  message += `*Failed Actions:*\n`;
  errorProducts.forEach(p => message += `  • ${p}\n`);
}

return [{ json: {
    message: message,
    successCount: successCount,
    errorCount: errorCount,
    validationFailedCount: validationFailedCount,
    totalProcessed: items.length
  }}];

// Analyze Agent Metrics from KV store
const status = $input.first().json;

// Extract key metrics
const metrics = {
  version: status.version || 'v4',
  architecture: status.architecture || 'two-phase-pipeline',
  models: status.model || { planner: 'gpt-4o-mini', answerer: 'gpt-4o' },
  capabilities: status.capabilities || [],
  available: status.available || true
};

// Simulate daily stats (in production, fetch from KV)
const dailyStats = {
  totalRequests: Math.floor(Math.random() * 100) + 50,
  avgResponseTime: Math.floor(Math.random() * 2000) + 1000,
  tokensUsed: Math.floor(Math.random() * 50000) + 10000,
  errorRate: (Math.random() * 5).toFixed(2),
  toolUsageRate: (Math.random() * 80 + 20).toFixed(2),
  topTools: [
    { name: 'get_products', count: Math.floor(Math.random() * 30) + 10 },
    { name: 'get_sales_stats', count: Math.floor(Math.random() * 20) + 5 },
    { name: 'calculate_unit_economics', count: Math.floor(Math.random() * 15) + 3 }
  ]
};

return {
  json: {
    metrics,
    dailyStats,
    timestamp: new Date().toISOString()
  }
};

const data = $input.first().json;
const stats = data.dailyStats;

let message = `🤖 *AI Agent Performance Report*

`;
message += `📊 *Daily Statistics*
`;
message += `• Total Requests: ${stats.totalRequests}
`;
message += `• Avg Response Time: ${stats.avgResponseTime}ms
`;
message += `• Tokens Used: ${stats.tokensUsed.toLocaleString()}
`;
message += `• Error Rate: ${stats.errorRate}%
`;
message += `• Tool Usage: ${stats.toolUsageRate}%

`;

message += `🔧 *Top Tools*
`;
stats.topTools.forEach((tool, i) => {
  message += `${i + 1}. ${tool.name}: ${tool.count} calls
`;
});

message += `
🏗️ *Architecture*
`;
message += `• Version: ${data.metrics.version}
`;
message += `• Pipeline: ${data.metrics.architecture}
`;
message += `• Planner: ${data.metrics.models.planner}
`;
message += `• Answerer: ${data.metrics.models.answerer}
`;

if (stats.avgResponseTime > 5000) {
  message += `
⚠️ *Alert: High Latency Detected*
`;
  message += `Average response time exceeds 5 seconds. Consider optimization.`;
}

return {
  json: {
    message: message,
    hasIssues: stats.avgResponseTime > 5000 || stats.errorRate > 5
  }
};

// Optimization recommendations based on metrics
const data = $input.first().json;

const recommendations = [];

if (data.dailyStats.avgResponseTime > 5000) {
  recommendations.push({
    issue: 'High Latency',
    action: 'Enable Dynamic Model Selection',
    impact: 'Reduce response time by 30-40%',
    priority: 'HIGH'
  });
}

if (data.dailyStats.errorRate > 5) {
  recommendations.push({
    issue: 'High Error Rate',
    action: 'Review tool executors and add fallbacks',
    impact: 'Improve reliability',
    priority: 'CRITICAL'
  });
}

if (data.dailyStats.toolUsageRate < 50) {
  recommendations.push({
    issue: 'Low Tool Usage',
    action: 'Refine system prompt to encourage tool calling',
    impact: 'Better data-driven responses',
    priority: 'MEDIUM'
  });
}

let message = `🔧 *AI Agent Optimization Recommendations*

`;

if (recommendations.length === 0) {
  message += `✅ No critical issues detected. Agent performing well!`;
} else {
  recommendations.forEach((rec, i) => {
    message += `${i + 1}. *${rec.issue}*
`;
    message += `   Action: ${rec.action}
`;
    message += `   Impact: ${rec.impact}
`;
    message += `   Priority: ${rec.priority}

`;
  });
}

return {
  json: {
    message: message,
    recommendations: recommendations
  }
};

// Tool Usage Analysis
const data = $input.first().json;
const tools = data.dailyStats.topTools;

let message = `📊 *Tool Usage Deep Dive*

`;

tools.forEach((tool, i) => {
  const percentage = ((tool.count / data.dailyStats.totalRequests) * 100).toFixed(1);
  message += `${i + 1}. *${tool.name}*
`;
  message += `   Calls: ${tool.count} (${percentage}%)

`;
});

message += `
💡 *Insights*
`;

const topTool = tools[0];
if (topTool.name === 'get_products') {
  message += `• Users frequently check product lists
`;
  message += `• Consider caching product data
`;
} else if (topTool.name === 'search_web') {
  message += `• High external search usage
`;
  message += `• Users seeking external information
`;
}

return {
  json: {
    message: message
  }
};

// Parse incoming Telegram message
const body = $input.first().json.body || $input.first().json;
const message = body.message || {};
const chatId = message.chat?.id || message.from?.id;
const text = message.text || '';
const userId = message.from?.id;
const username = message.from?.username || message.from?.first_name || 'User';

// Check if admin
const adminId = $('Configuration1').first().json.adminTelegramId;
const isAdmin = String(userId) === String(adminId);

return [{ json: {
    chatId: chatId,
    userId: userId,
    username: username,
    text: text,
    isAdmin: isAdmin,
    timestamp: new Date().toISOString()
  }}];

// Build context for AI Agent
const userMessage = $('Parse Telegram Message').first().json;
const metrics = $('Get System Metrics').first().json || {};
const analytics = $input.first().json?.analytics || {};

const systemContext = {
  timestamp: new Date().toISOString(),
  api_status: metrics.success ? 'healthy' : 'error',
  subscriptions: {
    active: analytics.subscriptions?.active || 0,
    expiring_soon: analytics.subscriptions?.expiring_soon || 0
  },
  sentinel: {
    total_actions: analytics.sentinel?.total_actions || 0,
    success_rate: analytics.sentinel?.success_rate || 0,
    errors_last_hour: metrics.metrics?.sentinel?.errors_last_hour || 0
  },
  products: {
    protected: analytics.products?.total_protected || 0,
    users_with_protection: analytics.products?.users_with_protection || 0
  },
  money_saved: analytics.money_saved?.total_rub || 0
};

return [{ json: {
    userMessage: userMessage.text,
    chatId: userMessage.chatId,
    username: userMessage.username,
    systemContext: systemContext
  }}];

const aiResponse = $input.first().json;
const context = $('Build AI Context').first().json;
let responseText = aiResponse.response?.text || aiResponse.text || aiResponse.message || 'Произошла ошибка.';
if (aiResponse.error) { responseText = 'Ошибка: ' + aiResponse.error; }
return [{ json: { chat_id: context.chatId, text: responseText }}];

// Get results from both Ozon and WB syncs
const ozonResult = $('Sync Ozon Products').first()?.json || {};
const wbResult = $input.first()?.json || {};

// API returns 'count' field for synced products
const ozonSynced = ozonResult.count || ozonResult.synced || 0;
const wbSynced = wbResult.count || wbResult.synced || 0;

// Check for errors (error field or non-success response)
const ozonError = ozonResult.error || (!ozonResult.success && ozonResult.count === undefined);
const wbError = wbResult.error || (!wbResult.success && wbResult.count === undefined);
const hasErrors = ozonError || wbError;

// Build detailed error info
let errorDetails = '';
if (ozonError && typeof ozonResult.error === 'string') {
  errorDetails += `\n❌ Ozon: ${ozonResult.error}`;
  if (ozonResult.details) errorDetails += ` (${ozonResult.details.substring(0, 100)})`;
}
if (wbError && typeof wbResult.error === 'string') {
  errorDetails += `\n❌ WB: ${wbResult.error}`;
  if (wbResult.details) errorDetails += ` (${wbResult.details.substring(0, 100)})`;
}

const message = `📦 Sync Complete\n\n` +
  `🔵 Ozon: ${ozonSynced} товаров` + (ozonError ? ' ❌' : ' ✅') + `\n` +
  `🟣 WB: ${wbSynced} товаров` + (wbError ? ' ❌' : ' ✅') +
  (hasErrors ? errorDetails : '') + `\n` +
  `⏰ ${new Date().toLocaleString('ru-RU')}`;

return [{ json: {
    ozonSynced: ozonSynced,
    wbSynced: wbSynced,
    hasErrors: !!hasErrors,
    ozonError: ozonError ? (ozonResult.error || 'Unknown') : null,
    wbError: wbError ? (wbResult.error || 'Unknown') : null,
    message: message
  }}];

const user = $input.item.json;
const expiresAt = new Date(user.expires_at);
const now = new Date();
const daysLeft = Math.ceil((expiresAt - now) / (1000 * 60 * 60 * 24));

let message = '';
let emoji = '';

if (daysLeft <= 1) {
  emoji = '🔴';
  message = `${emoji} *Подписка истекает сегодня!*\n\n`;
  message += `Ваша подписка NeuroGUARDIAN заканчивается через ${daysLeft} день.\n\n`;
  message += `⚠️ После окончания подписки:\n`;
  message += `• Сторож перестанет защищать ваши цены\n`;
  message += `• AI-агент будет недоступен\n`;
  message += `• Синхронизация товаров остановится\n\n`;
  message += `💡 Продлите подписку прямо сейчас, чтобы не потерять защиту!`;
} else if (daysLeft <= 3) {
  emoji = '🟡';
  message = `${emoji} *Подписка заканчивается через ${daysLeft} дня*\n\n`;
  message += `Не забудьте продлить подписку NeuroGUARDIAN!\n\n`;
  message += `Ваши товары под защитой ещё ${daysLeft} дня.\n\n`;
  message += `Продлите сейчас со скидкой 10% по промокоду: RENEW10`;
}

return [{ json: {
    telegram_id: user.telegram_id,
    message: message,
    days_left: daysLeft,
    expires_at: user.expires_at
  }}];

const items = $input.all();
const totalSent = items.length;

const message = `📬 *Notification Report*\n\n✅ Sent: ${totalSent} reminders\n\nUsers notified about expiring subscriptions.`;

return [{ json: {
    message: message,
    total_sent: totalSent
  }}];

const metricsResult = $input.first()?.json || {};

const issues = [];
let status = 'healthy';

// Check API health
if (!metricsResult.success) {
  issues.push('❌ API не отвечает');
  status = 'critical';
}

// Check expiring subscriptions
const expiringCount = metricsResult.metrics?.subscriptions?.expiring_soon?.length || 0;
if (expiringCount > 0) {
  issues.push(`⚠️ Истекает подписок: ${expiringCount}`);
  if (status === 'healthy') status = 'warning';
}

// Check Sentinel errors
const sentinelErrors = metricsResult.metrics?.sentinel?.errors_last_hour || 0;
if (sentinelErrors > 10) {
  issues.push(`⚠️ Sentinel ошибок за час: ${sentinelErrors}`);
  if (status === 'healthy') status = 'warning';
}

let message = '';
if (status === 'healthy') {
  message = `✅ *NeuroGUARDIAN Health Report*

` +
    `🟢 API: Работает
` +
    `🛡️ Sentinel: OK
` +
    `📊 Подписки: OK
` +
    `⏰ ${new Date().toLocaleString('ru-RU')}`;
} else {
  message = `⚠️ *NeuroGUARDIAN Alert*

` +
    `Status: ${status.toUpperCase()}

` +
    `Проблемы:
${issues.join('
')}

` +
    `⏰ ${new Date().toLocaleString('ru-RU')}`;
}

return [{ json: {
    status: status,
    issues: issues,
    message: message,
    shouldNotify: status !== 'healthy',
    metricsResult: metricsResult
  }}];

const data = $input.first()?.json?.analytics || {};

const formatNumber = (num) => {
  return new Intl.NumberFormat('ru-RU').format(num || 0);
};

const formatMoney = (num) => {
  return new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB' }).format(num || 0);
};

const message = `📊 *NeuroGUARDIAN — Ежедневный Отчёт*\n\n` +
  `📅 Период: последние 24 часа\n` +
  `⏰ ${new Date().toLocaleString('ru-RU')}\n\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n\n` +
  `👥 *Подписки*\n` +
  `✅ Активных: ${formatNumber(data.subscriptions?.active)}\n` +
  `⚠️ Истекают скоро: ${formatNumber(data.subscriptions?.expiring_soon)}\n\n` +
  `🛡️ *Защищённые товары*\n` +
  `📦 Всего: ${formatNumber(data.products?.total_protected)}\n` +
  `👤 Пользователей: ${formatNumber(data.products?.users_with_protection)}\n` +
  `💰 Средняя мин. цена: ${formatMoney(data.products?.avg_min_price)}\n\n` +
  `⚡ *Sentinel (за 24ч)*\n` +
  `🔧 Всего действий: ${formatNumber(data.sentinel?.total_actions)}\n` +
  `💵 Корректировок цен: ${formatNumber(data.sentinel?.price_corrections)}\n` +
  `📉 Обнулений остатков: ${formatNumber(data.sentinel?.zero_stocks)}\n` +
  `✅ Успешных: ${formatNumber(data.sentinel?.successful)}\n` +
  `❌ Ошибок: ${formatNumber(data.sentinel?.failed)}\n` +
  `📈 Success Rate: ${data.sentinel?.success_rate || 0}%\n\n` +
  `💸 *Сохранено денег*\n` +
  `${formatMoney(data.money_saved?.total_rub)}\n\n` +
  `👥 *Активность*\n` +
  `Активных пользователей: ${formatNumber(data.users?.active_last_24h)}\n\n` +
  `━━━━━━━━━━━━━━━━━━━━━━`;

return [{ json: {
    message: message,
    hasData: !!data.timestamp,
    analytics: data
  }}];

// Parse command from webhook or heartbeat
const input = $input.first().json;
let command = 'heartbeat';
let params = {};

if (input.body) {
  // From webhook
  const text = input.body.message?.text || '';
  const parts = text.split(' ');
  command = parts[0]?.replace('/', '') || 'status';
  params = { args: parts.slice(1) };
} else if (input.command) {
  // Direct call
  command = input.command;
  params = input.params || {};
}

return [{ json: {
    command: command,
    params: params,
    timestamp: new Date().toISOString(),
    source: input.body ? 'webhook' : 'scheduler'
  }}];

const metrics = $input.first().json;
const m = metrics.metrics || {};

const apiStatus = metrics.success ? '🟢 Online' : '🔴 Offline';
const sentinelErrors = m.sentinel?.errors_last_hour || 0;
const sentinelStatus = sentinelErrors < 5 ? '🟢 OK' : sentinelErrors < 20 ? '🟡 Warning' : '🔴 Critical';

const message = `📊 *NeuroGUARDIAN Status*\n\n` +
  `🌐 API: ${apiStatus}\n` +
  `🛡️ Sentinel: ${sentinelStatus}\n` +
  `├─ Errors (1h): ${sentinelErrors}\n` +
  `└─ Actions today: ${m.sentinel?.total_actions_today || 0}\n\n` +
  `👥 Users: ${m.subscriptions?.active_count || 0} active\n` +
  `📦 Products: ${m.products?.protected_count || 0} protected\n\n` +
  `⏰ ${new Date().toLocaleString('ru-RU')}`;

return [{ json: {
    message: message,
    chat_id: $('Configuration').first().json.adminChatId
  }}];

const result = $input.first().json;
const success = result.success || result.count !== undefined;

const message = success
  ? `✅ *Resync Complete*\n\nSynced ${result.count || 0} products.\n\n⏰ ${new Date().toLocaleString('ru-RU')}`
  : `❌ *Resync Failed*\n\nError: ${result.error || 'Unknown'}\n\n⏰ ${new Date().toLocaleString('ru-RU')}`;

return [{ json: {
    message: message,
    chat_id: $('Configuration').first().json.adminChatId
  }}];

const data = $input.first().json;
const violations = data.violations || [];
const totalChecked = data.totalChecked || 0;

let message = `🛡️ *Sentinel Status*\n\n`;
message += `📊 Checked: ${totalChecked} products\n`;
message += `⚠️ Violations: ${violations.length}\n\n`;

if (violations.length > 0) {
  message += `*Recent Violations:*\n`;
  violations.slice(0, 5).forEach((v, i) => {
    const emoji = v.marketplace === 'WB' ? '🟣' : '🔵';
    message += `${i + 1}. ${emoji} ${v.title?.substring(0, 30)}...\n`;
    message += `   ${v.action}: ${v.currentPrice}₽ → ${v.expectedPrice}₽\n`;
  });
  if (violations.length > 5) {
    message += `\n_...и ещё ${violations.length - 5}_\n`;
  }
} else {
  message += `✅ All prices are correct!\n`;
}

message += `\n⏰ ${new Date().toLocaleString('ru-RU')}`;

return [{ json: {
    message: message,
    chat_id: $('Configuration').first().json.adminChatId
  }}];

const result = $input.first().json;
const healthy = result.status === 'ok' || result.success;

// Only alert if unhealthy
if (!healthy) {
  return {
    json: {
      shouldAlert: true,
      message: `🚨 *ALERT: API DOWN*\n\nNeuroGUARDIAN API is not responding!\n\nError: ${result.error || 'Connection failed'}\n\n⏰ ${new Date().toLocaleString('ru-RU')}`,
      chat_id: $('Configuration').first().json.adminChatId
    }
  };
}

return [{ json: {
    shouldAlert: false,
    status: 'healthy'
  }}];

const message = `📖 *NeuroGUARDIAN Ops Commands*\n\n` +
  `/status — System status overview\n` +
  `/sentinel — Price protection report\n` +
  `/resync — Trigger full product sync\n` +
  `/help — Show this message\n\n` +
  `💡 Use AI Agent for natural language queries.`;

return [{ json: {
    message: message,
    chat_id: $('Configuration').first().json.adminChatId
  }}];
